{
  pkgs,
  username,
  lib,
  manageGuiApps ? false,
  ...
}:
{
  networking = {
    computerName = "My MacBook Pro";
    hostName = "My-MacBook-Pro";
    localHostName = "My-MacBook-Pro";
  };

  system = {
    # Primary user for user-specific settings
    primaryUser = username;

    # Keyboard remapping (caps lock → escape)
    keyboard.enableKeyMapping = true;
    keyboard.remapCapsLockToEscape = true;

    # macOS system preferences
    defaults = {
      # Dock settings
      dock = {
        autohide = true;
        autohide-time-modifier = 0.25;
        show-recents = false;
        tilesize = 32; # current system value
        largesize = 30;
        magnification = true;
        mineffect = "genie";
        minimize-to-application = false;
        mouse-over-hilite-stack = true;
        orientation = "bottom";
        launchanim = true;
        expose-group-apps = false;
      };

      # Finder settings
      finder = {
        AppleShowAllExtensions = true;
        AppleShowAllFiles = true;
        ShowPathbar = false; # current system
        ShowStatusBar = true;
        FXEnableExtensionChangeWarning = false;
        CreateDesktop = true;
        FXPreferredViewStyle = "icnv"; # icon view (current system)
        _FXShowPosixPathInTitle = true;
      };

      # Trackpad settings
      trackpad = {
        Clicking = true;
        TrackpadThreeFingerDrag = false;
        TrackpadRightClick = true;
      };

      # Global settings
      NSGlobalDomain = {
        AppleShowAllExtensions = true;
        InitialKeyRepeat = 30; # current system (lower = faster)
        KeyRepeat = 5; # current system (lower = faster)
        ApplePressAndHoldEnabled = false; # Enable key repeat
        AppleInterfaceStyleSwitchesAutomatically = true; # Auto dark mode
        AppleICUForce24HourTime = true; # 24 hour time
        AppleTemperatureUnit = "Celsius";
        AppleWindowTabbingMode = "always";
        AppleKeyboardUIMode = 2; # Full keyboard access
        NSAutomaticSpellingCorrectionEnabled = false;
        NSAutomaticCapitalizationEnabled = true; # current system
        NSAutomaticDashSubstitutionEnabled = true; # current system
        NSAutomaticPeriodSubstitutionEnabled = false;
        NSAutomaticQuoteSubstitutionEnabled = true; # current system
        NSAutomaticInlinePredictionEnabled = false;
      };

      # Screenshot settings
      screencapture = {
        location = "~/Downloads";
        disable-shadow = true;
        type = "jpg";
        show-thumbnail = true;
      };

      # Menu bar clock
      menuExtraClock = {
        Show24Hour = true;
        ShowDate = 2; # Always show date
        ShowDayOfWeek = false;
        ShowSeconds = false;
      };

      # Login window
      loginwindow = {
        GuestEnabled = false;
      };

      smb.NetBIOSName = "My-MacBook-Pro";

      # Prevent .DS_Store on network/USB drives
      CustomUserPreferences = {
        "com.apple.desktopservices" = {
          DSDontWriteNetworkStores = true;
          DSDontWriteUSBStores = true;
        };
        # Rectangle window manager
        "com.knollsoft.Rectangle" = {
          launchOnLogin = true;
          alternateDefaultShortcuts = true;
        };
        # Terminal
        "com.apple.Terminal" = {
          FocusFollowsMouse = true;
          "Default Window Settings" = "Pro";
        };
      };
    };

    activationScripts.macosDefaults.text = ''
      bun_bin="$(command -v bun || true)"
      if [ -n "$bun_bin" ]; then
        HOME="/Users/${username}" /usr/bin/sudo -u ${username} "$bun_bin" ${./script/macos.ts} || true
      fi
    '';

    # Required for nix-darwin
    stateVersion = 5;
  };

  # Nix settings (managed by Determinate, not nix-darwin)
  nix.enable = false;

  # System packages (minimal, rest via home-manager)
  environment.systemPackages = with pkgs; [
    vim
  ];

  # Enable Touch ID for sudo
  security.pam.services.sudo_local.touchIdAuth = true;
  security.pam.services.sudo_local.reattach = true;

  # Raise the launchd file-descriptor soft limit (macOS default is 256). Under heavy
  # multi-agent / Electron loads the syspolicyd Gatekeeper daemon hits EMFILE verifying
  # large bundles and falsely reports notarized apps as "damaged and can't be opened".
  # Restart syspolicyd so it re-spawns under the raised limit instead of its boot value.
  launchd.daemons.raise-maxfiles.serviceConfig = {
    ProgramArguments = [
      "/bin/sh"
      "-c"
      "launchctl limit maxfiles 65536 524288; killall syspolicyd 2>/dev/null || true"
    ];
    RunAtLoad = true;
  };

  # Homebrew (declarative management)
  homebrew = {
    enable = true;
    onActivation = {
      autoUpdate = false;
      upgrade = false;
      cleanup = "none";
    };
    taps = lib.optionals manageGuiApps [
    ];

    # CLI tools (macOS-specific or not in nix)
    # Core CLI tools are in shared.nix (nix) for cross-platform support
    brews = [
      # Git extras
      "gitui"

      # Node/JS ecosystem (brew manages versions better)
      "node"
      "node@22"
      "nvm"
      "pnpm"
      "yarn"

      # Python (brew manages versions better)
      "pipx"
      "python@3.12"
      "python@3.10"
      "virtualenv"
      "fastapi"
      "jupyterlab"

      # Shell extras
      "thefuck"
      "zsh-autosuggestions"
      "zsh-completions"
      "zsh-syntax-highlighting"

      # OCR & documents (macOS specific libs)
      "tesseract"
      "tesseract-lang"
      "ocrmypdf"

      # Containers & infra (macOS integration)
      "docker"
      "docker-compose"
      "tailscale"
      "cloudflared"

      # Network tools
      "tcpdump"
      "telnet"
      "lftp"
      "privoxy"

      # Misc tools
      "act"

      "repomix"
      "commitizen"
      "sshpass"
      "rlwrap"
      "cmatrix"

      # GUI automation (mouse/keyboard control via CLI)
      "cliclick"

      # External display DDC control (Apple Silicon)
      "m1ddc"

      # Security/networking
      "aircrack-ng"
      "hashcat"
      "hcxtools"

      # Remote development
      "coder"

      # Additional runtimes
      "php"

      # Media (macOS specific libs)
      "graphicsmagick"
      "telegram-downloader"
      "vips"
      "gstreamer"

      # Torrents
      "autobrr"
    ];

    extraConfig = ''
      brew "mpecan/tokf/tokf", trusted: true
    '';

    casks = [
      "macs-fan-control"
    ]
    ++ lib.optionals manageGuiApps [
      # Productivity
      "raycast"
      "rectangle"
      "alt-tab"
      "bartender"

      "maccy"
      "itsycal"

      # Development
      "iterm2"
      "warp"
      "cursor"
      "github"
      "mitmproxy"
      "wireshark-app"
      "ngrok"

      # Browsers
      "google-chrome"

      # Media
      "iina"
      "vlc"
      "obs"
      "audacity"
      "blackhole-2ch" # virtual audio driver — routes MetalVoice (AI voice) output into OBS/ScreenFlow

      # Utilities
      "appcleaner"
      "keka"
      "cleanshot"
      "stats"
      "monitorcontrol"
      "betterdisplay"
      "bettertouchtool"
      "lulu"
      "little-snitch"
      "keycastr"
      "latest"

      # Cloud & sync
      "google-drive"
      "dropzone"
      "motrix"

      # Communication
      "slack"
      "discord"
      "zoom"
      "notion"
      "telegram"

      # Design
      "figma"
      "canva"
      "imageoptim"

      # Media server
      "plex-media-server"

      # QuickLook plugins
      "qlmarkdown"
      "suspicious-package"

      # Fonts
      "font-fira-code"
      "font-hack-nerd-font"
      "font-bebas-neue"
      "font-inconsolata"
      "font-pt-serif"
      "font-readex-pro"

      # Window managers & input
      # instant-space-switcher is built from Baltsat fork in setup.sh
      "multitouch"
      "intellidock"
      "scroll-reverser"

      # Development extras
      "cursor-cli"
      "chromedriver"
      "android-platform-tools"
      "sf-symbols"

      # Utilities
      "apparency"
      "clop"
      "context"
      "find-empty-folders"
      "glance-chamburr"
      "hazeover"
      "one-switch"
      "pally"
      "pdf-squeezer"
      "pine"
      "reminders-menubar"
      "serverbuddy"
      "swift-quit"
      "table-tool"
      "tempbox"
      "time-out"
      "unclack"

      # Network & VPN
      "network-radar"
      "vibetunnel"
      "http-toolkit"
      "tunnelblick"

      # Cloud CLIs
      "gcloud-cli"

      # Media
      "droid"
      "riverside-studio"
      "macmediakeyforwarder"

      # Yandex
      "yandex-music-unofficial"
    ];
  };

  # User configuration
  # nix uses mkMerge to avoid "dynamic attribute already defined" when mixing
  # ${username} interpolation with a literal "root" attribute.
  users.users = lib.mkMerge [
    {
      ${username} = {
        name = username;
        home = "/Users/${username}";
      };
    }
    # nix-darwin 25.05+ requires root.home to be explicitly set
    { root.home = lib.mkForce "/var/root"; }
  ];

}

